import json,html,shutil
from pathlib import Path
D=json.loads(Path('data/research.json').read_text());E=D['events'];S=D['sports'];out=Path('_site');out.mkdir(exist_ok=True)
h=lambda x:html.escape(str(x or ''))
def link(url,label):return f'<a href="{h(url)}" target="_blank" rel="noopener noreferrer">{h(label)} ↗</a>' if url else ''
def page(file,title,body):
 text=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Evidence-first OLBG sports research, event inventory and pricing readiness."><title>{h(title)} · OLBG Research Desk</title><link rel="stylesheet" href="assets/style.css"><script defer src="assets/app.js"></script></head><body><header><a class="brand" href="index.html">OLBG <span>/ Research Desk</span></a><nav aria-label="Main navigation"><a href="../index.html">Main dashboard</a><a href="index.html">Overview</a><a href="picks.html">Our picks</a><a href="events.html">Event inventory</a><a href="pricing.html">Pricing lab</a><a href="review.html">Flagged for Review</a></nav></header><main>{body}</main><footer>Independent research project · Not affiliated with OLBG · Snapshot: {D['as_of']} UTC · Not a live odds feed · <a href="data/research.json">Download data</a> · <a href="data/SOURCES.md">Source audit</a><br>No guaranteed outcomes. Follow local gambling laws and age restrictions. Never wager money you cannot afford to lose.</footer></body></html>'''
 (out/file).write_text(text)
def intro(k,t,desc):return f'<div class="eyebrow">{k}</div><h1>{t}</h1><p class="lead">{desc}</p>'
def table(head,body):return '<div class="table-wrap"><table><thead><tr>'+''.join('<th scope="col">'+h(x)+'</th>' for x in head)+'</tr></thead><tbody>'+body+'</tbody></table></div>'
def event_table(events):
 rows=''
 for r in events:
  rows+=f'<tr data-sport="{h(r["sport"])}"><td>{h(r["event"])}<p><small>{h(r["sport"])} · ID {h(r["event_id"])}</small></p></td><td>{h(r["display_time"])}<p><small>OLBG display only; timezone unresolved unless UTC below</small></p>{h(r["start_utc"])}</td><td>{h(r["market"])}</td><td></td><td></td><td><span class="pill warn">Unverified / no pick</span></td><td>{link(r["source"],"OLBG listing")}<p>{link(r["official_source"],"Official fixture")}</p><small>{h(r["official_fact"])}</small></td></tr>'
 return table(['Event / sport','Source time / confirmed UTC','Observed markets','Our selection','Fair odds','Research status','Evidence'],rows) if events else '<div class="empty"><h3>No event rows captured</h3><p>The extracted snooker page said “No tips found.” This is not proof that no fixtures or markets exist.</p></div>'
def toolbar():return '<div class="toolbar"><label>Find an event <input id="search" type="search" placeholder="Search teams, players, markets…"></label><label>Sport <select id="sport-filter"><option value="">All 15 sports</option>'+''.join(f'<option>{h(s["name"])}</option>' for s in S)+'</select></label><span id="result-count" aria-live="polite">'+str(len(E))+' entries shown</span></div>'
empty='<div class="empty"><span class="pill warn">Selections withheld</span><h3>No publishable predictions yet</h3><p>Missing prices, current-form evidence, availability reports and calibrated independent probabilities prevent responsible selections.<br>Blank fields are intentional; community tip percentages are not our confidence ratings.</p><a href="review.html">See the blockers and evidence →</a></div>'
cards=''.join(f'<article class="card"><span class="eyebrow">{sum(r["sport"]==s["name"] for r in E)} observed events · 0 picks</span><h3>{h(s["name"])}</h3><p>{"No tips found in extraction" if s["name"]=="Snooker" else "Partial inventory · evidence incomplete"}</p><a href="sport-{s["slug"].lower()}.html">Open sport desk →</a></article>' for s in S)
page('index.html','Executive summary',intro('Research briefing / 26 October 2026','A clearer view. A higher evidence bar.','Your sports research desk: event listings, independent pricing readiness and clearly separated selections. Start with the summary, then drill into a sport or inspect the evidence.')+f'<div class="stats"><div class="stat"><strong>15</strong><span>Sports in scope</span></div><div class="stat"><strong>{len(E)}</strong><span>Observed event listings</span></div><div class="stat"><strong>0</strong><span>Published selections</span></div><div class="stat"><strong>0 / 15</strong><span>Operational pricing engines</span></div></div><div class="notice"><strong>Executive summary — no actionable picks today.</strong><br>This is a partial research snapshot, not a complete or continuously updated OLBG feed. Some listings have official fixture matches, but none meet the full publication requirements. The daily target of five written picks per sport has not been met.</div><div class="section-head"><h2>Highest-confidence picks · today & upcoming</h2><a href="picks.html">Go to our picks →</a></div>'+empty+'<div class="section-head"><h2>Choose your sport</h2><a href="events.html">View all events →</a></div><div class="grid">'+cards+'</div>')
page('picks.html','Our picks',intro('Selections / explicit publication status','Our picks','Only fully sourced, independently priced, upcoming selections belong here. Target: five per sport daily; never a forced quota.')+empty+table(['Sport','Target','Published','Gap / evidence'],''.join(f'<tr><td><a href="sport-{s["slug"].lower()}.html">{h(s["name"])}</a></td><td>5</td><td>0</td><td>5 · {link(s["url"],"OLBG sport source")}</td></tr>' for s in S)))
page('events.html','Event inventory',intro('Discovery / not recommendations','Observed event inventory','These are source-listed events, not our predictions. Raw relative times have not been assigned calendar dates. Blank selection and fair-odds cells mean not established. Every row links directly to OLBG; official fixture links appear only where checked.')+toolbar()+event_table(E))
for s in S:
 events=[r for r in E if r['sport']==s['name']]
 page('sport-'+s['slug'].lower()+'.html',s['name'],intro('Sport desk / '+s['checked'],h(s['name']),'0 written predictions published. Five per day is the target, not a guarantee of qualifying opportunities.')+f'<p>{link(s["url"],"OLBG sport page")} · <a href="pricing.html">Pricing requirements</a> · <a href="review.html">Review blockers</a></p>'+empty+'<h2>Observed listings</h2>'+event_table(events)+f'<article class="card"><h3>Pricing approach · not operational</h3><p>{h(s["method"])}</p><p>Markets to investigate: {h(s["markets"])}</p><p>{h(s["coverage"])}</p></article>')
pricing_rows=''.join(f'<tr><td>{h(s["name"])}</td><td>{h(s["method"])}</td><td>{h(s["markets"])}</td><td>Unfitted / no event lines</td><td>{link(s["url"],"OLBG scope")}</td></tr>' for s in S)
page('pricing.html','Pricing lab',intro('Research engineering / specifications','Independent lines, not copied prices.','Every sport has a proposed pricing approach. These are engineering specifications, not tested predictive systems or generated event odds. Source links establish OLBG sport scope, not validation of the proposed mathematics.')+'<div class="notice"><strong>Critical distinction:</strong> converting bookmaker odds into probabilities, removing margin, or copying community support does not originate an independent line. Historical official results, feature provenance, out-of-sample calibration and settlement rules are prerequisites.</div>'+table(['Sport','Required inputs & proposed calculation','Markets to investigate, availability unconfirmed','Readiness','Source'],pricing_rows)+'''<h2>Publication and calculation policy</h2><article class="card"><p>Proposed confidence labels: high ≥70%, medium 55–70%, low &lt;55%, only after calibration. Probability is not evidence quality. High-confidence publication also requires positive expected value, official match evidence and uncertainty review.</p><p>Allowed offered odds: −250 through +10000, inclusive. At −250 the break-even probability is 71.43%; at +10000 it is 0.99%. A 70% estimate is not a value bet at −250. No odds imply certainty.</p><p>Fair decimal odds = 1 / p for no-push outcomes. With pushes, fair decimal = 1 + P(loss) / P(win). EV per unit = P(win) × (decimal odds − 1) − P(loss). Keep draw, push, dead-heat, retirement, withdrawal and overtime rules separate.</p><p>Proposed workflow: official fixture identity → current roster and form → independently fitted distribution → all observed markets → quoted price and timestamp → value and uncertainty gates → original 30+ word analysis → stale/start-time checks. Unknown facts remain blank. No unsupported “no injuries” claims.</p><p>Implemented: tested probability/price arithmetic and conservative publication guard in <code>scripts/pricing.py</code>. Not implemented: fitted sport-specific engines, calibrated probabilities, exhaustive market feeds or automated editorial production.</p></article>''')
issues=[('Coverage incomplete','Only captured excerpts are inventoried. Load More, expired filters and event detail markets are not exhaustively enumerated. No claim of a full list.', 'https://www.olbg.com/betting-tips'),('Prices absent','Fetched event detail shows WIN @ with no numeric odds. No bookmaker, timestamp or executable price was captured. Odds and lines remain blank.',next(r['source'] for r in E if r['sport']=='Baseball')),('Percentages are community support','OLBG describes the percentage as the share of tips backing an outcome. It cannot be presented as an independent win probability.','https://www.olbg.com/betting-tips'),('Conflicting displayed times','Cricket and ice-hockey overview times differ by four hours from sport pages. Retain original display strings and do not infer timezone.','https://www.olbg.com/betting-tips/Cricket/7'),('Greyhound eligibility','8:24 Towcester is explicitly marked Expired. Race labels differ from displayed times. All captured races require fresh eligibility checks.','https://www.olbg.com/betting-tips/Greyhounds/28'),('Snooker empty extraction','No tips found is a source observation, not proof of an empty official fixture calendar.','https://www.olbg.com/betting-tips/Snooker/8'),('Handball draw concentration','Many extracted popular selections say Tie. Do not interpret popularity as a reliable draw probability. Settlement and full outcome lists need checking.','https://www.olbg.com/betting-tips/Handball/20'),('Official NBA extraction limited','NBA schedule page returned navigation and filters without fixtures. No NBA matchup has been officially matched in this dataset.','https://www.nba.com/schedule'),('Official ATP scope mismatch','ATP current page exposes live and completed scores. No captured future OLBG tennis row has been matched to an official draw or order of play.','https://www.atptour.com/en/scores/current'),('Official cricket dates incomplete','ICC fixtures show matching opponents and formats, but extracted local times do not establish absolute dates. Match detail returned loading placeholders.','https://www.icc-cricket.com/fixtures-results'),('Darts official extraction blocked by consent text','PDC calendar retrieval returned extensive cookie preferences. Calendar content was not established.','https://www.pdc.tv/calendar/'),('No form/injury evidence','No event has a complete official current-form, head-to-head/statistics and availability evidence set. No predictions generated from OLBG comments.','https://www.olbg.com/betting-tips'),('No fitted pricing engines','Sport-specific methods are design proposals only. No trained/calibrated independent event lines exist.','https://www.olbg.com/betting-tips')]
page('review.html','Flagged for Review',intro('Audit trail / non-blocking research issues','Flagged for Review','Unsupported values are left blank. These issues do not block publication of the research dashboard, but they do block publication of betting selections.')+table(['Issue','Finding / required resolution','Source for manual review'],''.join(f'<tr><td>{h(a)}</td><td>{h(b)}</td><td>{link(c,"Source")}</td></tr>' for a,b,c in issues))+'<h2>Row-level evidence gaps</h2>'+table(['Event','Flags','OLBG source','Checked official source'],''.join(f'<tr><td>{h(r["event"])}</td><td><ul>'+''.join('<li>'+h(f)+'</li>' for f in r['flags'])+f'</ul></td><td>{link(r["source"],"OLBG")}</td><td>{link(r["official_source"],"Official fixture")}</td></tr>' for r in E)))
shutil.copytree('assets',out/'assets',dirs_exist_ok=True);shutil.copytree('data',out/'data',dirs_exist_ok=True)
shutil.copy('data/SOURCES.md',out/'data'/'SOURCES.md')
(out/'.nojekyll').touch()
import sys
if '--publish' in sys.argv:
 for file in out.glob('*.html'):shutil.copy(file,Path(file.name))
 Path('.nojekyll').touch()
print(f'Built {len(list(out.glob("*.html")))} pages; {len(E)} research rows; zero invented selections.')
